    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    float alpha = 1.0f;
    float beta = 0.0f;

    // rocBLAS uses column-major ordering, so we compute B^T * A^T = (A * B)^T
    // C = A * B in row-major is equivalent to C^T = B^T * A^T in column-major
