        B.data_ptr<float>(), N,  // B is K x N in row-major, so ldb = N
        A.data_ptr<float>(), K,  // A is M x K in row-major, so lda = K
        &beta,
        C.data_ptr<float>(), N   // C is M x N in row-major, so ldc = N
